<?php
require_once __DIR__.'/../includes/auth.php';require_login();$bid=current_branch_id();$q=trim($_GET['q']??'');
$members=$trainers=$payments=[];if($q!==''){$like="%$q%";
if(user()['role']!=='accountant'){if(user()['role']==='trainer'){$tid=(int)(query_value('SELECT id FROM trainers WHERE user_id=?',[user()['id']])?:0);$members=query_all("SELECT id,member_code,CONCAT(first_name,' ',last_name) name,phone,status FROM members WHERE branch_id=? AND trainer_id=? AND (member_code LIKE ? OR CONCAT(first_name,' ',last_name) LIKE ? OR phone LIKE ? OR email LIKE ?) LIMIT 20",[$bid,$tid,$like,$like,$like,$like]);}else{$members=query_all("SELECT id,member_code,CONCAT(first_name,' ',last_name) name,phone,status FROM members WHERE branch_id=? AND (member_code LIKE ? OR CONCAT(first_name,' ',last_name) LIKE ? OR phone LIKE ? OR email LIKE ?) LIMIT 20",[$bid,$like,$like,$like,$like]);}}
if(in_array(user()['role'],['super_admin','manager','receptionist']))$trainers=query_all("SELECT id,name,email,phone,specialization FROM trainers WHERE branch_id=? AND (name LIKE ? OR email LIKE ? OR phone LIKE ?) LIMIT 15",[$bid,$like,$like,$like]);
if(in_array(user()['role'],['super_admin','manager','receptionist','accountant']))$payments=query_all("SELECT p.id,p.reference_no,p.amount,p.payment_date,CONCAT(m.first_name,' ',m.last_name) member_name FROM payments p JOIN members m ON m.id=p.member_id WHERE p.branch_id=? AND (p.reference_no LIKE ? OR CONCAT(m.first_name,' ',m.last_name) LIKE ?) LIMIT 20",[$bid,$like,$like]);}
$pageTitle='Global Search';include __DIR__.'/../includes/header.php';?>
<div class="panel mb-3"><form class="search search-large" method="get"><i class="fa-solid fa-magnifying-glass"></i><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Search member name, ID, phone, trainer or payment reference..." autofocus></form></div>
<?php if($q===''):?><div class="panel"><p class="text-muted mb-0">Type something to search across the current branch.</p></div><?php else:?>
<div class="grid-2"><?php if(user()['role']!=='accountant'): ?><div class="panel"><div class="panel-head"><div><h3>Members</h3><p><?= count($members) ?> result(s)</p></div></div><div class="mini-list"><?php foreach($members as $m):?><a class="mini-row" href="<?= url('app/member_view.php?id='.$m['id']) ?>"><div class="mini-avatar"><?= e(initials($m['name'])) ?></div><div class="grow"><strong><?= e($m['name']) ?></strong><small><?= e($m['member_code']) ?> · <?= e($m['phone']) ?></small></div><span class="badge-soft badge-<?= status_badge($m['status']) ?>"><?= e($m['status']) ?></span></a><?php endforeach;if(!$members):?><p class="text-muted small">No member match.</p><?php endif;?></div></div><?php endif; ?>
<div class="panel"><div class="panel-head"><div><h3>Payments</h3><p><?= count($payments) ?> result(s)</p></div></div><div class="mini-list"><?php foreach($payments as $p):?><a class="mini-row" href="<?= url('app/payment_receipt.php?id='.$p['id']) ?>"><div class="mini-avatar"><i class="fa-solid fa-receipt"></i></div><div class="grow"><strong><?= e($p['reference_no']) ?> · <?= e($p['member_name']) ?></strong><small><?= format_date($p['payment_date']) ?> · <?= money($p['amount']) ?></small></div></a><?php endforeach;if(!$payments):?><p class="text-muted small">No payment match.</p><?php endif;?></div></div></div>
<?php if($trainers):?><div class="panel mt-3"><div class="panel-head"><div><h3>Trainers</h3></div></div><div class="mini-list"><?php foreach($trainers as $t):?><div class="mini-row"><div class="mini-avatar"><i class="fa-solid fa-dumbbell"></i></div><div class="grow"><strong><?= e($t['name']) ?></strong><small><?= e($t['specialization']) ?> · <?= e($t['phone']) ?></small></div></div><?php endforeach;?></div></div><?php endif;?>
<?php endif;include __DIR__.'/../includes/footer.php';?>
